INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q1 Item 1 (TPS 2015): Com relação às ideias desenvolvidas no texto anterior, julgue (C ou E) os itens subsequentes. | Infere-se do texto que uma das características marcantes da pós-modernidade é a valorização do referente, no contexto das representações do real.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q1 Item 2 (TPS 2015): Com relação às ideias desenvolvidas no texto anterior, julgue (C ou E) os itens subsequentes. | Ao comentar a distinção entre espetáculo e simulacro, o autor demonstra, com base em analistas do tema, como a pós-modernidade se manifesta de modo evidente por meio de uma cultura de espetáculo a ser usufruída pela sociedade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q1 Item 3 (TPS 2015): Com relação às ideias desenvolvidas no texto anterior, julgue (C ou E) os itens subsequentes. | O Brasil, segundo o autor do texto, é um dos países que poderá resolver a oposição entre espetáculo e simulacro, uma vez que “já tem a sua história” (R. 60 e 61).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q1 Item 4 (TPS 2015): Com relação às ideias desenvolvidas no texto anterior, julgue (C ou E) os itens subsequentes. | O autor do texto comenta que teóricos modernos da pós-modernidade valorizam a noção de simulacro. Esses mesmos teóricos passam a dirigir críticas à noção de espetáculo (que ocorre, por exemplo, em museus).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q2 Item 1 (TPS 2015): Com relação aos sentidos e ao emprego de palavras e expressões no texto de Silviano Santiago, julgue (C ou E) os itens seguintes. | Dados os sentidos do texto e o sentido de oni-, a expressão “a onipresença da imagem” (R.22) deve ser interpretada, no texto, como a presença da imagem em todos os lugares e dimensões.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q2 Item 2 (TPS 2015): Com relação aos sentidos e ao emprego de palavras e expressões no texto de Silviano Santiago, julgue (C ou E) os itens seguintes. | As expressões latinas “in corpore” (R.31) e “in absentia” (R.32) são utilizadas, no texto, com sentido antitético.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q2 Item 3 (TPS 2015): Com relação aos sentidos e ao emprego de palavras e expressões no texto de Silviano Santiago, julgue (C ou E) os itens seguintes. | A expressão “concepção triádica” (R. 18 e 19), extratextualmente, poderia também ser utilizada para representar a Santíssima Trindade, doutrina acolhida pela maioria das igrejas cristãs.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q2 Item 4 (TPS 2015): Com relação aos sentidos e ao emprego de palavras e expressões no texto de Silviano Santiago, julgue (C ou E) os itens seguintes. | O verbo circunscrever foi empregado no primeiro período do segundo parágrafo com o sentido de originar, ser a causa de, derivar. ||154IRBRDIPLOMATA2015_001_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q3 Item 1 (TPS 2015): Em setembro de 1916, Fernando Pessoa pensava que o n.º 3 da revista Orpheu ainda poderia vir à luz. E, de fato, chega a entrar no prelo, imprimindo-se apenas algumas folhas. No sumário, como se depreende da carta a Cortes Rodrigues de 4 desse mês, deveriam figurar poemas ingleses do profeta do “supra-Camões” e “colaboração variada” do seu “velho e infeliz amigo Álvaro de Campos”. Vale a pena reparar nos adjetivos deploradores que o poeta junta, nessa data, ao nome do seu heterônimo dileto. Parec | No texto, o autor informa que o abandono do acento circunflexo no sobrenome representou, para o poeta português, uma revolução estética considerável, que faria do autor de Passos da Cruz um escritor muito mais vanguardista do que antes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q3 Item 2 (TPS 2015): Em setembro de 1916, Fernando Pessoa pensava que o n.º 3 da revista Orpheu ainda poderia vir à luz. E, de fato, chega a entrar no prelo, imprimindo-se apenas algumas folhas. No sumário, como se depreende da carta a Cortes Rodrigues de 4 desse mês, deveriam figurar poemas ingleses do profeta do “supra-Camões” e “colaboração variada” do seu “velho e infeliz amigo Álvaro de Campos”. Vale a pena reparar nos adjetivos deploradores que o poeta junta, nessa data, ao nome do seu heterônimo dileto. Parec | Fernando Pessoa escreveu poemas que não poderiam jamais ser traduzidos para a língua inglesa, uma vez que na Inglaterra aqueles mesmos poemas seriam considerados muito indecentes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q3 Item 3 (TPS 2015): Em setembro de 1916, Fernando Pessoa pensava que o n.º 3 da revista Orpheu ainda poderia vir à luz. E, de fato, chega a entrar no prelo, imprimindo-se apenas algumas folhas. No sumário, como se depreende da carta a Cortes Rodrigues de 4 desse mês, deveriam figurar poemas ingleses do profeta do “supra-Camões” e “colaboração variada” do seu “velho e infeliz amigo Álvaro de Campos”. Vale a pena reparar nos adjetivos deploradores que o poeta junta, nessa data, ao nome do seu heterônimo dileto. Parec | Do texto, cujo autor afirma que Fernando Pessoa não conseguiu ver impressos os seus poemas no número 3 da revista Orpheu, mesmo porque aquela edição acabou não sendo publicada, não se pode inferir o motivo da não publicação da revista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q3 Item 4 (TPS 2015): Em setembro de 1916, Fernando Pessoa pensava que o n.º 3 da revista Orpheu ainda poderia vir à luz. E, de fato, chega a entrar no prelo, imprimindo-se apenas algumas folhas. No sumário, como se depreende da carta a Cortes Rodrigues de 4 desse mês, deveriam figurar poemas ingleses do profeta do “supra-Camões” e “colaboração variada” do seu “velho e infeliz amigo Álvaro de Campos”. Vale a pena reparar nos adjetivos deploradores que o poeta junta, nessa data, ao nome do seu heterônimo dileto. Parec | Segundo o autor do texto, durante todo o tempo em que utilizou o acento circunflexo no sobrenome, o poeta português estava sendo paradoxal e querendo provocar humor por conta daquele erro de acentuação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Inglesa', NULL, 'Q4 Item 1 (TPS 2015):  | Num carro, a caminho do Alto da Boa Vista, sigo com alguns jovens — alguns extremamente jovens — que se embriagam e rompem ampolas de Kelene, em cujo rótulo leio', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Inglesa', NULL, 'Q4 Item 2 (TPS 2015):  | anestesiante. Sim, é fértil em recursos essa mocidade, mas do que precisamente procura ela se anestesiar? Nenhum deles sofre de algum mal profundo — e, no entanto, esse mal pior de 7 não sofrer de mal nenhum... — e são hábeis e versados nessas coisas de éter e entorpecentes, pronunciando esse nome — Kelene — com familiaridade, nome sem dúvida mais que usual 10 nos hospitais, mas que ouço pela primeira vez e onde julgo distinguir inquietas ressonâncias, sombrias previsões, o não sei que tom amputado e doloroso, que reflete salas de hospitais, 13 asilos de alienados e antros escuros de vícios, todos os lugares enfim onde a alma impaciente pode passear sem arroubos finais seus gritos destruidores. Kelene, mesmo inocente, tem, 16 no frio do seu jato efêmero e cristalino, toda uma melodia secre', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Inglesa', NULL, 'Q5 Item 1 (TPS 2015):  | Celso Cunha tinha, na minha geração literária, a posição que, na geração anterior à nossa, coube a Souza da Silveira. Ou seja: a do mestre que, conhecendo profundamente', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Inglesa', NULL, 'Q5 Item 2 (TPS 2015):  | a língua portuguesa, nas suas minúcias e no seu conjunto, associou a esse saber admirável a sensibilidade de quem nascera para apreciá-la na condição de obra de arte. 7 Antes do mestre das Lições de Português, tivéramos aqui as sucessivas gerações dos professores que se consideravam exímios na colocação dos pronomes, na guerra 10 sistemática aos galicismos, na sujeição aos modelos clássicos, e, com isto, impunham mais o terror gramatical que o saber verdadeiro.13 Houve quem passasse a escrever registo, em vez de registro, e preguntar, em vez de perguntar, porque assim se escrevia em Portugal. Já ao tempo de José de Alencar, 16 um publicista ríspido, José Feliciano de Castilho, viera de Lisboa para o Rio de Janeiro, com a missão de ensinar-nos a escrever como se escrevia em Portugal. Daí a ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Inglesa', NULL, 'Q5 Item 3 (TPS 2015):  | Nestes quatrocentos anos de colonização literária, recebemos a influência de muitos países. Sempre tentamos reproduzir, com todas as minudências, a língua, as ideias, a', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Inglesa', NULL, 'Q5 Item 4 (TPS 2015):  | vida de outras terras. Não sei donde vem esse medo que temos de sermos nós mesmos. Queremos que nos tomem por outros. (...) 7 Na literatura de ficção é que a falta de caráter dos brasileiros se revelou escandalosamente. Em geral, os nossos escritores mostraram uma admirável ignorância das coisas que 10 estavam perto deles. Tivemos caboclos brutos semelhantes aos heróis cristãos e bem-falantes em excesso. Os patriotas do século passado, em vez de estudar os índios, estudaram tupi 13 nos livros e leram Walter Scott. Tivemos damas das camélias em segunda mão. Tivemos paisagens inúteis em linguagem campanuda, pores do sol difíceis, queimadas enormes, secas 16 cheias de adjetivos. José Veríssimo construiu um candeeiro em não sei quantas páginas. Muito pouco — rios, poentes cor de sangue, 19 inc', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q6 Item 2 (TPS 2015): Com base nas ideias desenvolvidas no texto anterior, julgue (C ou E) os itens seguintes. | A frase “Tivemos damas das camélias em segunda mão” (R. 13 e 14) expressa, em linguagem figurada, o que Graciliano denomina “contrafação de literaturas estranhas” (R.34) e, como indica o emprego da expressão “em segunda mão”, o desapreço do autor à produção literária que revelava tal influência.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q6 Item 3 (TPS 2015): Com base nas ideias desenvolvidas no texto anterior, julgue (C ou E) os itens seguintes. | A sentença “José Veríssimo construiu um candeeiro em não sei quantas páginas” (R. 16 e 17) é metáfora que expressa a crítica de Graciliano à descrição pormenorizada utilizada por José Veríssimo, em detrimento da construção de personagens verossímeis e de obras em cujo enredo ações e diálogos fossem adequados às figuras nelas retratadas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q6 Item 4 (TPS 2015): Com base nas ideias desenvolvidas no texto anterior, julgue (C ou E) os itens seguintes. | Depreende-se do texto que, segundo o autor, a colonização cultural no Brasil ultrapassou o período da colonização política, fato evidenciado na dificuldade de afirmação da identidade literária brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q7 Item 1 (TPS 2015): Julgue (C ou E) os próximos itens, relativos a aspectos gramaticais do texto de Graciliano Ramos. | A expressão “toda essa gente” (R.41) retoma o complemento do adjetivo “cheias” no segmento de sentido conotativo “cheias de nomes novos” (R.40).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q7 Item 2 (TPS 2015): Julgue (C ou E) os próximos itens, relativos a aspectos gramaticais do texto de Graciliano Ramos. | O termo “de outras terras” (R.4) especifica os três núcleos do complemento do verbo “reproduzir” (R.3) — “língua”, “ideias” e “vida”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q7 Item 3 (TPS 2015): Julgue (C ou E) os próximos itens, relativos a aspectos gramaticais do texto de Graciliano Ramos. | Dada a posição que ocupa na oração, o termo adverbial “Na literatura de ficção” (R.7) deveria estar isolado por vírgula, se atendido o rigor gramatical.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q7 Item 4 (TPS 2015): Julgue (C ou E) os próximos itens, relativos a aspectos gramaticais do texto de Graciliano Ramos. | Os termos “escandalosamente” (R.8) e “bonito” (R.27) exercem, nas orações a que pertencem, a mesma função sintática.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q8 Item 1 (TPS 2015):  | Sei que fazer o inconexo aclara as loucuras. Sou formado em desencontros. A sensatez me absurda.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q8 Item 2 (TPS 2015):  | Os delírios verbais me terapeutam. Posso dar alegria ao esgoto (palavra aceita tudo). (E sei de Baudelaire que passou muitos meses tenso 7 porque não encontrava um título para os seus poemas. Um título que harmonizasse os seus conflitos. Até que apareceu Flores do mal. A beleza e a dor. Essa antítese o 10 acalmou.) As antíteses congraçam. Manoel de Barros. Livro sobre nada. Rio de Janeiro: Record, 1997, p. 49. Julgue (C ou E) os itens seguintes, relativos ao poema de Manoel de Barros. 1 No trecho “E sei de Baudelaire que passou muitos meses tenso” (v.6), a omissão da vírgula necessária para isolar a oração adjetiva explicativa introduzida pelo pronome “que” é desvio da norma gramatical circunscrito à denominada licença poética. 2 O último verso do poema — “As antíteses congraçam” — resume ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q9 Item 1 (TPS 2015):  | O subúrbio de S. Geraldo, no ano de 192..., já misturava ao cheiro de estrebaria algum progresso. Quanto mais fábricas se abriam nos arredores, mais o subúrbio se', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q9 Item 2 (TPS 2015):  | erguia em vida própria, sem que os habitantes pudessem dizer que transformação os atingia. Os movimentos já se haviam congestionado e não se poderia atravessar uma rua sem 7 desviar-se de uma carroça que os cavalos vagarosos puxavam, enquanto um automóvel impaciente buzinava atrás lançando fumaça. Mesmo os crepúsculos eram agora enfumaçados e 10 sanguinolentos. De manhã, entre os caminhões que pediam passagem para a nova usina, transportando madeira e ferro, as cestas de peixe se espalhavam pela calçada, vindas, através da 13 noite, de centros maiores. Dos sobrados desciam mulheres despenteadas com panelas, os peixes eram pesados quase na mão, enquanto os vendedores em mangas de camisa gritavam 16 os preços. E quando, sobre o alegre movimento da manhã, soprava o vento fresco e perturbador,', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q9 Item 3 (TPS 2015):  | Distingo, no português histórico, dois períodos principais: o português antigo, que se escreveu até os primeiros anos do século XVI, e o português moderno. Robustecida e', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q9 Item 4 (TPS 2015):  | enriquecida de expressões novas, a linguagem usada nas crônicas desse segundo período, que relatam os descobrimentos em África e Ásia e os feitos das armas 7 lusitanas no Oriente, culmina no apuro e no gosto do português moderno d’Os Lusíadas (1572). É o século da Renascença literária, e tudo quanto ao depois se escreve é a continuação da 10 linguagem desse período. E como não ficou estacionário o português moderno, denominou-se quinhentista, seiscentista, setecentista a linguagem própria a cada era. Reservo a 13 denominação de português hodierno para as mudanças características do falar atual criadas ou fixadas recentemente, ou recebidas do século XIX, ou que por ventura remontam ao 16 século XVIII. Limites entre os diversos períodos não podem ser traçados com rigor. Ignoram-se a data ou ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q10 Item 1 (TPS 2015): Acerca das ideias do texto de M. Said Ali, julgue (C ou E) os itens que se seguem. | Infere-se do desenvolvimento das ideias no segundo parágrafo do texto que pessoas instruídas inicialmente rejeitam uma inovação na língua; entretanto, passado algum tempo, incorporam-na à escrita, de forma refletida, assim como à linguagem empregada nos relacionamentos íntimos e no cotidiano.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q10 Item 2 (TPS 2015): Acerca das ideias do texto de M. Said Ali, julgue (C ou E) os itens que se seguem. | Segundo o autor, os escritores portugueses, tendo adotado, após 1500, o falar comum da gente instruída em suas obras literárias, refinando-o, atingiram seu intento de transformar a língua oral e reformar o português antigo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q10 Item 3 (TPS 2015): Acerca das ideias do texto de M. Said Ali, julgue (C ou E) os itens que se seguem. | Depreende-se do texto que, nas crônicas escritas em português moderno, a linguagem, fortalecida e renovada, atingiu seu mais alto grau de aperfeiçoamento e estilo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q10 Item 4 (TPS 2015): Acerca das ideias do texto de M. Said Ali, julgue (C ou E) os itens que se seguem. | As noções de tempo “hodierno” (R.13), “atual” (R.14) e “recentemente” (R.14) têm como referência o século XX.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q11 Item 1 (TPS 2015): Julgue (C ou E) os itens a seguir, a respeito de elementos coesivos e do vocabulário do texto de M. Said Ali. | Na linha 17, a expressão “os diversos períodos” refere-se não só à oposição entre português antigo e moderno, mas também aos períodos que compõem o português moderno, como o seiscentista, o setecentista e até o do português hodierno.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q11 Item 2 (TPS 2015): Julgue (C ou E) os itens a seguir, a respeito de elementos coesivos e do vocabulário do texto de M. Said Ali. | O vocábulo “inveterados” (R.35) foi empregado como sinônimo de obsoletos, podendo ser substituído por essa palavra sem prejuízo para o sentido e para a correção gramatical do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q11 Item 3 (TPS 2015): Julgue (C ou E) os itens a seguir, a respeito de elementos coesivos e do vocabulário do texto de M. Said Ali. | As formas verbais “sucumbe” (R.25) e “desterrando” (R.42), que poderiam ser corretamente substituídas, respectivamente, por não resiste e livrando-se de, foram assim empregadas no texto: a primeira, em sentido denotativo, e a segunda, em sentido conotativo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q11 Item 4 (TPS 2015): Julgue (C ou E) os itens a seguir, a respeito de elementos coesivos e do vocabulário do texto de M. Said Ali. | Em textos contemporâneos, a expressão “por ventura” (R.15) tem como variante o vocábulo porventura, cujo sentido equivale a talvez.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q12 Item 1 (TPS 2015): Cada um dos itens subsequentes apresenta uma proposta de reescrita de trecho do texto de M. Said Ali, que deve ser julgada certa se estiver devidamente pontuada e gramaticalmente correta e mantiver as informações do texto, ou errada, em caso contrário. 1 “Decorrem muitos anos, até que por fim a linguagem literária, não vendo razão para enjeitar o que todo o mundo diz, se decide a aceitar a mudança também.” (R. 27 a 30): Passa-se muito tempo, até que a linguagem literária, finalmente, por não enc | No modesto apartamento em que mora na rua Conde de Bonfim, Graciliano Ramos mostrou-me alguns originais dos seus trabalhos. Via de regra, escreve em papel sem pautas, de', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q12 Item 2 (TPS 2015): Cada um dos itens subsequentes apresenta uma proposta de reescrita de trecho do texto de M. Said Ali, que deve ser julgada certa se estiver devidamente pontuada e gramaticalmente correta e mantiver as informações do texto, ou errada, em caso contrário. 1 “Decorrem muitos anos, até que por fim a linguagem literária, não vendo razão para enjeitar o que todo o mundo diz, se decide a aceitar a mudança também.” (R. 27 a 30): Passa-se muito tempo, até que a linguagem literária, finalmente, por não enc | um só golpe, ao calor da composição. A forma definitiva vem depois. Emenda muito. E até mesmo quando passa a limpo, com sua letra explicativa de escrevente de cartório, corta muita 7 coisa, tudo o que depois vai achando ruim. Às vezes risca linhas inteiras. As palavras morrem sob o traço forte de tinta de uma igualdade assombrosa, como feito à régua. 10 Graciliano guarda os originais dos livros já publicados. Assim pude verificar um curioso detalhe da feitura de Vidas S', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q13 Item 1 (TPS 2015): A respeito da linguagem e do vocabulário empregados no texto anterior, julgue (C ou E) os itens seguintes. | No terceiro parágrafo, o repórter abandona a narrativa e, sem intervir, reproduz, em discurso direto, o relato de Graciliano Ramos acerca da produção de Vidas Secas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q13 Item 2 (TPS 2015): A respeito da linguagem e do vocabulário empregados no texto anterior, julgue (C ou E) os itens seguintes. | Embora contenha trechos de fala, o texto está isento de coloquialismo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q13 Item 3 (TPS 2015): A respeito da linguagem e do vocabulário empregados no texto anterior, julgue (C ou E) os itens seguintes. | No primeiro parágrafo, o emprego, em sentido figurado, do substantivo “calor” (R.4) e da forma verbal “morrem” (R.8) contribuiu para a expressividade da linguagem dos segmentos em que esses vocábulos se inserem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q13 Item 4 (TPS 2015): A respeito da linguagem e do vocabulário empregados no texto anterior, julgue (C ou E) os itens seguintes. | Depreende-se que a qualidade de “explicativa” (R.6), atribuída à letra de Graciliano Ramos pelo autor do texto, foi empregada com o sentido de clara, legível, inteligível.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q14 Item 1 (TPS 2015): Julgue (C ou E) os próximos itens, a propósito das ideias e de aspectos morfossintáticos do texto de Francisco de Assis Barbosa. | Depreende-se do texto que poucas vezes Graciliano Ramos escreveu de chofre, mas quando o fez, reescreveu tudo depois, ao passar a limpo, e é por isso que, para ele, escrever era muito trabalhoso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q14 Item 2 (TPS 2015): Julgue (C ou E) os próximos itens, a propósito das ideias e de aspectos morfossintáticos do texto de Francisco de Assis Barbosa. | As informações e a correção gramatical do texto seriam preservadas, caso a conjunção aditiva “E” (R. 5 e 16) fosse grafada em minúscula; o ponto final que a antecede fosse substituído por vírgula; e, apenas na ocorrência da linha 5, essa conjunção fosse seguida de vírgula.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q14 Item 3 (TPS 2015): Julgue (C ou E) os próximos itens, a propósito das ideias e de aspectos morfossintáticos do texto de Francisco de Assis Barbosa. | A supressão da vírgula empregada logo após “livro” (R.17) atenderia às normas gramaticais, porém violaria a coerência do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q14 Item 4 (TPS 2015): Julgue (C ou E) os próximos itens, a propósito das ideias e de aspectos morfossintáticos do texto de Francisco de Assis Barbosa. | O trecho “A vida de Graciliano Ramos está sempre presente na sua obra, no que ela tem de mais humano e doloroso.” (R. 24 e 25) poderia ser reescrito, sem prejuízo das informações originais do texto e de sua correção gramatical, da seguinte forma: Está sempre presente na obra de Graciliano Ramos aquilo que, na sua vida, é mais humano e doloroso. ||154IRBRDIPLOMATA2015_001_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015 POLÍTICA INTERNACIONAL', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q15 Item 1 (TPS 2015): Acerca da política externa norte-americana e das relações entre EUA e Brasil, julgue (C ou E) os seguintes itens. | Nos últimos dois anos, os EUA deixaram de ser o principal parceiro comercial do Brasil — posto ocupado pela China —, tornando sua relação comercial com o Brasil deficitária, embora mantenham o padrão de concentrar suas compras em matérias-primas e suas vendas em produtos industrializados e serviços.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q15 Item 2 (TPS 2015): Acerca da política externa norte-americana e das relações entre EUA e Brasil, julgue (C ou E) os seguintes itens. | EUA e Brasil estabeleceram estratégia de cooperação educacional por meio de um plano de ação negociado em nível ministerial, no qual se evitou envolver o setor privado, especialmente no programa Ciência sem Fronteiras, uma vez que a pesquisa de ponta concentra-se em universidades públicas nos EUA.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q15 Item 3 (TPS 2015): Acerca da política externa norte-americana e das relações entre EUA e Brasil, julgue (C ou E) os seguintes itens. | Devido ao apoio explícito dos EUA ao seu pleito por um assento permanente no Conselho de Segurança da ONU, o Brasil vem reconhecendo publicamente os avanços do país norte-americano em suas negociações diretas com a Federação Russa em favor do desarmamento nuclear.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q15 Item 4 (TPS 2015): Acerca da política externa norte-americana e das relações entre EUA e Brasil, julgue (C ou E) os seguintes itens. | Os temas prioritários nas relações bilaterais entre EUA e Brasil incluem a cooperação visando reduzir as desigualdades de gênero e eliminar progressivamente a violência contra a mulher e o tráfico de mulheres, cuja implementação consta em documento específico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q16 Item 1 (TPS 2015): A propósito das relações entre a União Europeia e o Brasil, julgue (C ou E) os itens a seguir. | Brasil e União Europeia continuam a cooperar em áreas de comércio, investimento e negócios, inclusive via negociação de acordo preferencial UE-MERCOSUL, uma vez que compartilham a frustração de ver adiada a conclusão da Rodada Doha.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q16 Item 3 (TPS 2015): A propósito das relações entre a União Europeia e o Brasil, julgue (C ou E) os itens a seguir. | Representantes de alto nível da Comissão Europeia e dos ministérios brasileiros do Desenvolvimento Social e Combate à Fome, da Previdência Social e do Trabalho e Emprego reúnem-se periodicamente para promover a cooperação sobre políticas sociais em temas como mudanças demográficas, direitos de trabalhadores migrantes e regimes especiais para trabalhadores rurais, entre outros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q16 Item 4 (TPS 2015): A propósito das relações entre a União Europeia e o Brasil, julgue (C ou E) os itens a seguir. | No marco de sua parceria estratégica, Brasil e União Europeia estabeleceram um plano de ação conjunto que enfatiza, com respeito à paz e à segurança, ações como a promoção dos direitos humanos e da democracia, a defesa da justiça internacional e o fortalecimento do sistema multilateral.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q17 Item 1 (TPS 2015): No que se refere à União Sul-Americana de Nações (UNASUL), julgue (C ou E) os itens subsecutivos. | A UNASUL visa aprofundar a cooperação regional; evita, pois, objetivos de integração regional, para não criar resistências políticas. Os esforços em prol da cooperação se empreendem no seio de seus doze conselhos, entre os quais se destacam o de educação e o de criação de medidas de confiança mútua.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q17 Item 2 (TPS 2015): No que se refere à União Sul-Americana de Nações (UNASUL), julgue (C ou E) os itens subsecutivos. | O Conselho de Defesa da UNASUL fixa a diretriz de reger-se pelos princípios estabelecidos nas cartas da ONU e da OEA, bem como pelos mandatos e decisões do Conselho de Chefas e Chefes de Estados e de Governo da UNASUL, respeitando, entre outros princípios, a soberania e a integridade dos Estados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q17 Item 3 (TPS 2015): No que se refere à União Sul-Americana de Nações (UNASUL), julgue (C ou E) os itens subsecutivos. | Entre os objetivos da UNASUL, figura o de promover a democracia, inclusive pela mediação de crises internacionais ou internas dos países membros, como ocorreu nos casos da tentativa separatista do Pando, na Bolívia, da sublevação da Polícia Nacional do Equador e da crise entre Colômbia e Venezuela.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q17 Item 4 (TPS 2015): No que se refere à União Sul-Americana de Nações (UNASUL), julgue (C ou E) os itens subsecutivos. | Como principal foro de condução do processo de integração da infraestrutura física sul-americana, a IIRSA implementa os consensos políticos a que chegam os ministros de pastas de infraestrutura dos países-membros da UNASUL, restando ao COSIPLAN a tarefa de levantar os recursos para realizar os investimentos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q18 Item 1 (TPS 2015): Julgue (C ou E) os itens subsequentes, relativos à política externa inglesa e suas relações com o Brasil. | O Reino Unido busca fazer do Brasil via de acesso aos mercados sul-americanos, razão pela qual tenta convencer os parceiros europeus a usarem o tratado de livre comércio existente entre Brasil e Reino Unido como base de negociação do acordo de livre comércio UE-MERCOSUL.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q18 Item 4 (TPS 2015): Julgue (C ou E) os itens subsequentes, relativos à política externa inglesa e suas relações com o Brasil. | Como consequência dos diálogos estratégicos de alto nível empreendidos pelos chefes de governo, o intercâmbio comercial entre o Brasil e o Reino Unido mais que triplicou nos últimos dez anos, alçando o Brasil ao grupo dos dez principais parceiros comerciais do Reino Unido. ||154IRBRDIPLOMATA2015_001_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q19 Item 1 (TPS 2015): Com relação às políticas externas da Rússia e da Alemanha e suas respectivas relações com o Brasil, julgue (C ou E) os itens a seguir. | Amplamente superavitária em seu comércio com o Brasil, a Alemanha concentra suas exportações em produtos manufaturados e importa, sobretudo, produtos básicos, como café, minérios e farelo de soja.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q19 Item 2 (TPS 2015): Com relação às políticas externas da Rússia e da Alemanha e suas respectivas relações com o Brasil, julgue (C ou E) os itens a seguir. | A Alemanha celebrou com o Brasil o Acordo sobre Parceria e Cooperação em Matéria de Segurança Pública, visando apoiar o Brasil na modernização de sua Polícia Federal, em troca das experiências brasileiras na organização de grandes eventos esportivos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q19 Item 3 (TPS 2015): Com relação às políticas externas da Rússia e da Alemanha e suas respectivas relações com o Brasil, julgue (C ou E) os itens a seguir. | A Federação Russa vem utilizando o BRICS como instrumento para fomentar o seu comércio bilateral com os demais países do agrupamento, o que levou ao crescimento sustentado de seu saldo comercial com o Brasil, que hoje figura entre os doze maiores parceiros comerciais russos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q19 Item 4 (TPS 2015): Com relação às políticas externas da Rússia e da Alemanha e suas respectivas relações com o Brasil, julgue (C ou E) os itens a seguir. | Brasil e Rússia convergem sobre temas da agenda internacional, como a reforma das estruturas de governança global, inclusive do Conselho de Segurança das Nações Unidas, mas divergem a respeito das ações destinadas a criar o Arranjo Contingencial de Reservas do BRICS.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q20 Item 1 (TPS 2015): Julgue (C ou E) os seguintes itens, que se referem às políticas externas brasileira e argentina e às relações entre os dois países. | A Argentina concentra suas exportações ao Brasil, seu principal parceiro comercial, em produtos básicos e suas importações, em serviços e produtos químicos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q20 Item 2 (TPS 2015): Julgue (C ou E) os seguintes itens, que se referem às políticas externas brasileira e argentina e às relações entre os dois países. | Os princípios que Brasil e Argentina compartilham na condução de suas respectivas políticas externas incluem a promoção da independência nacional e da integração regional na América Latina, o respeito aos direitos humanos e o fortalecimento do multilateralismo e do direito internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q20 Item 3 (TPS 2015): Julgue (C ou E) os seguintes itens, que se referem às políticas externas brasileira e argentina e às relações entre os dois países. | Em sua busca por crescente autonomia, o Brasil privilegiou a articulação multilateral no trato com países desenvolvidos e a construção de relações bilaterais estratégicas, como é a da Argentina, país com o qual assinou o Tratado de Itaipu nos anos 70 do século passado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Política Internacional', NULL, 'Q20 Item 4 (TPS 2015): Julgue (C ou E) os seguintes itens, que se referem às políticas externas brasileira e argentina e às relações entre os dois países. | A gradual construção de uma parceria estratégica entre Brasil e Argentina transformou a visão que cada país tinha do outro: de adversário a sócio na promoção de um espaço regional de paz e cooperação. Esse projeto de integração envolveu a cooperação em setores-chave, como o nuclear.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Direito Internacional Público', NULL, 'Q21 Item 1 (TPS 2015): Com relação à Comunidade dos Países de Língua Portuguesa (CPLP), julgue (C ou E) os seguintes itens. | A Empresa Brasileira de Pesquisa Agropecuária (EMBRAPA) tem sido, tradicionalmente, o principal agente brasileiro de cooperação em segurança alimentar e nutricional no âmbito da CPLP.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Direito Internacional Público', NULL, 'Q21 Item 2 (TPS 2015): Com relação à Comunidade dos Países de Língua Portuguesa (CPLP), julgue (C ou E) os seguintes itens. | A criação do Instituto Internacional de Língua Portuguesa, em 1989, precedeu a própria constituição da CPLP.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Direito Internacional Público', NULL, 'Q21 Item 3 (TPS 2015): Com relação à Comunidade dos Países de Língua Portuguesa (CPLP), julgue (C ou E) os seguintes itens. | Os Estados-membros da CPLP são Angola, Brasil, Cabo Verde, Guiné Bissau, Moçambique, Portugal, São Tomé e Príncipe e Timor Leste.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Direito Internacional Público', NULL, 'Q21 Item 4 (TPS 2015): Com relação à Comunidade dos Países de Língua Portuguesa (CPLP), julgue (C ou E) os seguintes itens. | A CPLP tem prestado apoio ao processo de reconciliação nacional em Guiné Bissau em coordenação com o secretário-geral das Nações Unidas, que possui um representante especial para Guiné Bissau.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q22 Item 1 (TPS 2015): Os BRICS, bem como outras economias de mercado emergentes e países em desenvolvimento, continuam a enfrentar restrições de financiamento significativas para lidar com lacunas de infraestrutura e necessidades de desenvolvimento sustentável. Tendo isso presente, temos satisfação em anunciar a assinatura do Acordo Constitutivo do Novo Banco de Desenvolvimento, com o propósito de mobilizar recursos para projetos de infraestrutura e desenvolvimento sustentável nos BRICS e em outras economias emergent | Acordou-se na VI Cúpula que o primeiro presidente do Novo Banco de Desenvolvimento seria da Rússia; o primeiro presidente de seu Conselho de Governadores, da Índia; e o primeiro presidente de seu Conselho de Administração, do Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q22 Item 2 (TPS 2015): Os BRICS, bem como outras economias de mercado emergentes e países em desenvolvimento, continuam a enfrentar restrições de financiamento significativas para lidar com lacunas de infraestrutura e necessidades de desenvolvimento sustentável. Tendo isso presente, temos satisfação em anunciar a assinatura do Acordo Constitutivo do Novo Banco de Desenvolvimento, com o propósito de mobilizar recursos para projetos de infraestrutura e desenvolvimento sustentável nos BRICS e em outras economias emergent | Foi acertado em Fortaleza que o Novo Banco de Desenvolvimento seria sediado em Xangai.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q22 Item 3 (TPS 2015): Os BRICS, bem como outras economias de mercado emergentes e países em desenvolvimento, continuam a enfrentar restrições de financiamento significativas para lidar com lacunas de infraestrutura e necessidades de desenvolvimento sustentável. Tendo isso presente, temos satisfação em anunciar a assinatura do Acordo Constitutivo do Novo Banco de Desenvolvimento, com o propósito de mobilizar recursos para projetos de infraestrutura e desenvolvimento sustentável nos BRICS e em outras economias emergent | Juntamente com o Acordo Constitutivo do Novo Banco de Desenvolvimento, foi assinado em Fortaleza o Tratado para o Estabelecimento do Arranjo Contingente de Reservas dos BRICS, com recursos iniciais da ordem de US$ 100 bilhões.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Língua Portuguesa', NULL, 'Q22 Item 4 (TPS 2015): Os BRICS, bem como outras economias de mercado emergentes e países em desenvolvimento, continuam a enfrentar restrições de financiamento significativas para lidar com lacunas de infraestrutura e necessidades de desenvolvimento sustentável. Tendo isso presente, temos satisfação em anunciar a assinatura do Acordo Constitutivo do Novo Banco de Desenvolvimento, com o propósito de mobilizar recursos para projetos de infraestrutura e desenvolvimento sustentável nos BRICS e em outras economias emergent | Definiu-se na Cúpula de Fortaleza que o Novo Banco de Desenvolvimento teria capital inicial autorizado de US$ 100 bilhões, com um capital inicial subscrito de US$ 50 bilhões, dividido igualmente entre seus membros fundadores. ||154IRBRDIPLOMATA2015_001_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q23 Item 1 (TPS 2015): Em relação ao fenômeno da mudança climática e a seu tratamento no marco das Conferências das Partes da Convenção-Quadro das Nações Unidas sobre Mudança do Clima, julgue (C ou E) os itens subsequentes. | A XVIII Conferência das Partes prorrogou o Protocolo de Quioto até 2030, embora sem o apoio de Japão, Rússia, Canadá e Nova Zelândia, além dos EUA, que nunca ratificaram o protocolo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q23 Item 2 (TPS 2015): Em relação ao fenômeno da mudança climática e a seu tratamento no marco das Conferências das Partes da Convenção-Quadro das Nações Unidas sobre Mudança do Clima, julgue (C ou E) os itens subsequentes. | A XX Conferência das Partes requereu a apresentação por todos os Estados-membros, até março de 2015, de metas de cortes de emissões, com o compromisso de apresentar planos e ações para conter o aquecimento após 2030.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q23 Item 3 (TPS 2015): Em relação ao fenômeno da mudança climática e a seu tratamento no marco das Conferências das Partes da Convenção-Quadro das Nações Unidas sobre Mudança do Clima, julgue (C ou E) os itens subsequentes. | Dados da NASA e da agência norte-americana NOAA (Administração Atmosférica e Oceânica Nacional) indicam que, na primeira década deste século, houve relativa estabilidade na temperatura média mundial, tendo as emissões de gases de efeito estufa continuado a aumentar, estimulando as negociações internacionais sobre o assunto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q23 Item 4 (TPS 2015): Em relação ao fenômeno da mudança climática e a seu tratamento no marco das Conferências das Partes da Convenção-Quadro das Nações Unidas sobre Mudança do Clima, julgue (C ou E) os itens subsequentes. | A III Conferência das Partes adotou, em 1997, o Protocolo de Quioto, que estabelecia o compromisso dos países desenvolvidos listados em seu Anexo I em reduzir, até 2012, 5,2% das suas emissões de gases de efeito estufa, em relação aos níveis de 1990.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q24 Item 1 (TPS 2015): À luz dos termos do Memorando de Entendimento relativo ao Contencioso do Algodão celebrado entre os governos do Brasil e dos EUA em outubro de 2014, em Washington, julgue (C ou E) os itens subsecutivos. | Além de limitar em dezoito meses o prazo máximo de empréstimos no tocante ao subsídio GSM-102 e estipular uma compensação anual no valor de 300 milhões de dólares, o referido memorando prevê que os recursos transferidos ao Instituto Brasileiro do Algodão podem ser destinados a projetos de cooperação com a África Subsaariana, o Haiti e os países-membros do MERCOSUL.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q24 Item 2 (TPS 2015): À luz dos termos do Memorando de Entendimento relativo ao Contencioso do Algodão celebrado entre os governos do Brasil e dos EUA em outubro de 2014, em Washington, julgue (C ou E) os itens subsecutivos. | O tempo de tramitação da disputa entre o Brasil e os EUA na OMC foi de dois anos e seis meses, desde a formalização do pedido de consultas sobre o assunto, em setembro de 2002, até a circulação, em março de 2005, do relatório sobre o recurso impetrado pelo governo norte-americano.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q24 Item 4 (TPS 2015): À luz dos termos do Memorando de Entendimento relativo ao Contencioso do Algodão celebrado entre os governos do Brasil e dos EUA em outubro de 2014, em Washington, julgue (C ou E) os itens subsecutivos. | O memorando em tela foi celebrado alguns meses após a adoção, pelo Congresso norte-americano, de nova legislação agrícola, que não mais previa subsídios ao setor de algodão.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q25 Item 1 (TPS 2015): É difícil aquilatar a importância relativa do conflito árabe com o Estado de Israel e, dentro dele, a questão Palestina na crise atual do Oriente Médio. Boa parte dos processos internos e inclusive dos conflitos externos no mundo muçulmano independe da existência desse conflito. Por outro lado, seu papel no discurso de legitimação — tanto interno como externo — dos diferentes governos, grupos políticos e correntes ideológicas, como a Irmandade Muçulmana, a Al-Qaeda e o ISIS, não pode ser ignorad | A Irmandade Muçulmana contou com apoio irrestrito das autoridades sauditas nas últimas décadas, apesar de sua oposição à intervenção norte-americana no Kuwait e, depois, no Iraque. Entretanto, os sauditas apoiaram a deposição de sua liderança no Egito quando ela sinalizou sua disposição em dialogar com o Irã e, em 2015, o governo saudita declarou a Irmandade Muçulmana uma organização terrorista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q25 Item 2 (TPS 2015): É difícil aquilatar a importância relativa do conflito árabe com o Estado de Israel e, dentro dele, a questão Palestina na crise atual do Oriente Médio. Boa parte dos processos internos e inclusive dos conflitos externos no mundo muçulmano independe da existência desse conflito. Por outro lado, seu papel no discurso de legitimação — tanto interno como externo — dos diferentes governos, grupos políticos e correntes ideológicas, como a Irmandade Muçulmana, a Al-Qaeda e o ISIS, não pode ser ignorad | A Guerra Civil na Síria é particularmente complexa: tanto a Arábia Saudita como a Turquia e a Irmandade Muçulmana (inclusive o Hamas) opõem-se ao governo de Bashar al-Assad, mas cada um deles apoia grupos diferentes de rebeldes, enquanto o governo de Damasco é apoiado pelo Irã, pela Rússia e pelo Hizbollah, que, por sua vez, é um aliado do Hamas no conflito com Israel.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q25 Item 3 (TPS 2015): É difícil aquilatar a importância relativa do conflito árabe com o Estado de Israel e, dentro dele, a questão Palestina na crise atual do Oriente Médio. Boa parte dos processos internos e inclusive dos conflitos externos no mundo muçulmano independe da existência desse conflito. Por outro lado, seu papel no discurso de legitimação — tanto interno como externo — dos diferentes governos, grupos políticos e correntes ideológicas, como a Irmandade Muçulmana, a Al-Qaeda e o ISIS, não pode ser ignorad | Entre as dificuldades identificadas pelos analistas para a modernização do mundo islâmico estão a persistência dos laços de família ampliada e da lealdade aos clãs, que limitam a afirmação individual; a reação patriarcal frente a um mundo ocidental que aprofunda a liberação feminina; e os problemas de pobreza e de baixo nível de escolaridade, que facilitam a entrada de organizações paraestatais que proveem serviços sociais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q25 Item 4 (TPS 2015): É difícil aquilatar a importância relativa do conflito árabe com o Estado de Israel e, dentro dele, a questão Palestina na crise atual do Oriente Médio. Boa parte dos processos internos e inclusive dos conflitos externos no mundo muçulmano independe da existência desse conflito. Por outro lado, seu papel no discurso de legitimação — tanto interno como externo — dos diferentes governos, grupos políticos e correntes ideológicas, como a Irmandade Muçulmana, a Al-Qaeda e o ISIS, não pode ser ignorad | A Irmandade Muçulmana, que foi organizada na Arábia Saudita em 1928 como reação à influência ocidental, defende, entre outras ideias, a implantação da Charia (lei corânica) e a unificação do mundo muçulmano, a ser imposta pela propaganda e pela força. ||154IRBRDIPLOMATA2015_001_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q26 Item 1 (TPS 2015): Sabendo que a Constituição Federal de 1988 determina a prevalência dos direitos humanos como um dos princípios que devem reger as relações internacionais do Brasil, além de abrir a possibilidade de que direitos reconhecidos em tratados internacionais se somem aos direitos e garantias fundamentais já consagrados no texto constitucional, julgue (C ou E) os seguintes itens. | O Brasil conta com juiz na Corte Interamericana de Direitos Humanos e integra a Comissão Interamericana de Direitos Humanos, tendo Brasília sediado sessão extraordinária da Corte Interamericana em novembro de 2013.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q26 Item 2 (TPS 2015): Sabendo que a Constituição Federal de 1988 determina a prevalência dos direitos humanos como um dos princípios que devem reger as relações internacionais do Brasil, além de abrir a possibilidade de que direitos reconhecidos em tratados internacionais se somem aos direitos e garantias fundamentais já consagrados no texto constitucional, julgue (C ou E) os seguintes itens. | Criado pela Assembleia Geral das Nações Unidas em 1948, o Conselho de Direitos Humanos realiza, entre outras iniciativas, a Revisão Periódica Universal, mecanismo que permite a avaliação da situação dos direitos humanos em todos os Estados-membros das Nações Unidas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q26 Item 3 (TPS 2015): Sabendo que a Constituição Federal de 1988 determina a prevalência dos direitos humanos como um dos princípios que devem reger as relações internacionais do Brasil, além de abrir a possibilidade de que direitos reconhecidos em tratados internacionais se somem aos direitos e garantias fundamentais já consagrados no texto constitucional, julgue (C ou E) os seguintes itens. | Na Revisão Periódica Universal realizada em 2012, o Brasil recebeu cento e setenta recomendações nas mais diferentes áreas, como desenvolvimento e inclusão social; promoção da igualdade; educação; segurança alimentar; moradia adequada; memória e verdade; segurança, justiça e sistema prisional; e povos indígenas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q26 Item 4 (TPS 2015): Sabendo que a Constituição Federal de 1988 determina a prevalência dos direitos humanos como um dos princípios que devem reger as relações internacionais do Brasil, além de abrir a possibilidade de que direitos reconhecidos em tratados internacionais se somem aos direitos e garantias fundamentais já consagrados no texto constitucional, julgue (C ou E) os seguintes itens. | Em 2013, a Assembleia Geral das Nações Unidas aprovou por consenso a resolução A/RES/68/167, intitulada O direito à privacidade na era digital, originalmente proposta por Brasil, Alemanha e EUA.GEOGRAFIA', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q27 Item 1 (TPS 2015): Em dois casos recentes, centenas de imigrantes ilegais morreram em naufrágios no mar Mediterrâneo. No primeiro deles, em 21 de abril, ocorreram cerca de oitocentas mortes. Segundo dados do Alto Comissariado das Nações Unidas para Refugiados, o que se verifica na atualidade é uma grave crise humanitária no mar Mediterrâneo, principal rota de entrada de refugiados e imigrantes ilegais no continente europeu. A respeito dessa crise, julgue (C ou E) os itens a seguir. | A maior parte dos migrantes que cruzam o Mediterrâneo são originários de países africanos e do Oriente Médio, regiões onde conflitos armados, miséria e perseguições estimulam a migração, tendo grande número de sírios passado a utilizar essa rota com a eclosão e o agravamento da guerra civil na Síria.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q27 Item 2 (TPS 2015): Em dois casos recentes, centenas de imigrantes ilegais morreram em naufrágios no mar Mediterrâneo. No primeiro deles, em 21 de abril, ocorreram cerca de oitocentas mortes. Segundo dados do Alto Comissariado das Nações Unidas para Refugiados, o que se verifica na atualidade é uma grave crise humanitária no mar Mediterrâneo, principal rota de entrada de refugiados e imigrantes ilegais no continente europeu. A respeito dessa crise, julgue (C ou E) os itens a seguir. | No começo do século XXI, a rota mais popular entre imigrantes ilegais situava-se entre o oeste africano e a Espanha, e incluía territórios espanhóis no norte da África, como Ceuta e Melilla, e as Ilhas Canárias. Porém, com a crise em diversos países do norte da África, como Líbia, Tunísia e Egito, houve mudança de rota, em razão da desarticulação política e dos sistemas de controle marítimo e de fronteiras desses países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q27 Item 3 (TPS 2015): Em dois casos recentes, centenas de imigrantes ilegais morreram em naufrágios no mar Mediterrâneo. No primeiro deles, em 21 de abril, ocorreram cerca de oitocentas mortes. Segundo dados do Alto Comissariado das Nações Unidas para Refugiados, o que se verifica na atualidade é uma grave crise humanitária no mar Mediterrâneo, principal rota de entrada de refugiados e imigrantes ilegais no continente europeu. A respeito dessa crise, julgue (C ou E) os itens a seguir. | A União Europeia não criminaliza a entrada de imigrantes ilegais no território de seus países-membros, o que incentiva pessoas oriundas da África, do Oriente Médio e da Europa Oriental a buscarem empregos e melhores condições de vida na Europa Ocidental.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q27 Item 4 (TPS 2015): Em dois casos recentes, centenas de imigrantes ilegais morreram em naufrágios no mar Mediterrâneo. No primeiro deles, em 21 de abril, ocorreram cerca de oitocentas mortes. Segundo dados do Alto Comissariado das Nações Unidas para Refugiados, o que se verifica na atualidade é uma grave crise humanitária no mar Mediterrâneo, principal rota de entrada de refugiados e imigrantes ilegais no continente europeu. A respeito dessa crise, julgue (C ou E) os itens a seguir. | Em 2015, intensificou-se ainda mais a saída de imigrantes a partir do Marrocos, que se tornou ponto de partida de muitas viagens, já que traficantes de pessoas aproveitam-se do caos político no país, onde milícias rivais estão em conflito.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q28 Item 1 (TPS 2015): Em 2008, os EUA vivenciaram o fenômeno conhecido como estouro da bolha imobiliária, que atingiu duramente a economia do país, a maior do planeta, e gerou ondas de impacto em escala global. Dois anos mais tarde, a crise atingiu a União Europeia, que se acreditava ser o mais sólido bloco econômico do mundo. No que se refere a esse assunto e a aspectos históricos a ele pertinentes, julgue (C ou E) os próximos itens. | A taxa de desemprego é um dos índices utilizados para se medir a gravidade da crise: os países mais industrializados e com nível tecnológico mais elevado, como Alemanha, França e Inglaterra, sofreram menos os efeitos da crise sobre as taxas de emprego, diferentemente de Itália e Portugal, por exemplo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q28 Item 2 (TPS 2015): Em 2008, os EUA vivenciaram o fenômeno conhecido como estouro da bolha imobiliária, que atingiu duramente a economia do país, a maior do planeta, e gerou ondas de impacto em escala global. Dois anos mais tarde, a crise atingiu a União Europeia, que se acreditava ser o mais sólido bloco econômico do mundo. No que se refere a esse assunto e a aspectos históricos a ele pertinentes, julgue (C ou E) os próximos itens. | A crise europeia expressa-se pela enorme dívida pública, ocasionada por gastos excessivos, com despesas maiores do que as receitas e sem o devido lastro de reservas, em países como Grécia, Itália, Irlanda, Portugal e Espanha.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q28 Item 3 (TPS 2015): Em 2008, os EUA vivenciaram o fenômeno conhecido como estouro da bolha imobiliária, que atingiu duramente a economia do país, a maior do planeta, e gerou ondas de impacto em escala global. Dois anos mais tarde, a crise atingiu a União Europeia, que se acreditava ser o mais sólido bloco econômico do mundo. No que se refere a esse assunto e a aspectos históricos a ele pertinentes, julgue (C ou E) os próximos itens. | O Tratado de Roma (1992), que instituiu a Comunidade Europeia, estabeleceu para os países-membros que a relação entre dívida pública e PIB não poderia ultrapassar o limite de 30%.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q28 Item 4 (TPS 2015): Em 2008, os EUA vivenciaram o fenômeno conhecido como estouro da bolha imobiliária, que atingiu duramente a economia do país, a maior do planeta, e gerou ondas de impacto em escala global. Dois anos mais tarde, a crise atingiu a União Europeia, que se acreditava ser o mais sólido bloco econômico do mundo. No que se refere a esse assunto e a aspectos históricos a ele pertinentes, julgue (C ou E) os próximos itens. | Em 2010, a relação dívida/PIB da Alemanha, da França e da Inglaterra estava bastante alta e acima do máximo estipulado pela União Europeia; entretanto, dado o fato de que esses países possuem economias altamente industrializadas, capacidade de investimento e grandes reservas internacionais controladas por seus bancos centrais, eventuais déficits em suas contas externas foram cobertos e ataques especulativos ao euro e à libra esterlina foram evitados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q29 Item 1 (TPS 2015): O Brasil, terceira maior potência mundial agropecuária, enfrenta desafios logísticos, de infraestrutura e legais para continuar a crescer nesse setor, competindo internacionalmente. No que se refere a esse assunto e aos múltiplos aspectos a ele relacionados, julgue (C ou E) os itens a seguir. | Os investimentos em infraestrutura no território brasileiro, incluindo energia elétrica e transportes, mediante privatizações, concessões de serviços públicos a empresas privadas e parcerias público-privadas, estão se tornando, gradativamente, um problema para o governo federal em razão do desinteresse de grandes empresas nesse tipo de negócio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q29 Item 2 (TPS 2015): O Brasil, terceira maior potência mundial agropecuária, enfrenta desafios logísticos, de infraestrutura e legais para continuar a crescer nesse setor, competindo internacionalmente. No que se refere a esse assunto e aos múltiplos aspectos a ele relacionados, julgue (C ou E) os itens a seguir. | As grandes distâncias entre as áreas produtoras de alimentos e os centros de industrialização, consumo, produção e portos, além de envolverem implicações de ordem local (ambiental, econômica, social, política), repercutem na escala nacional de uso do território brasileiro, dada a existência de fluxos de grande volume e baixo valor agregado entre regiões desprovidas de condições logísticas capazes de fazer frente às quantidades produzidas em larga escala.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q29 Item 3 (TPS 2015): O Brasil, terceira maior potência mundial agropecuária, enfrenta desafios logísticos, de infraestrutura e legais para continuar a crescer nesse setor, competindo internacionalmente. No que se refere a esse assunto e aos múltiplos aspectos a ele relacionados, julgue (C ou E) os itens a seguir. | O atual modelo de uso do território brasileiro é marcado por uma regulação híbrida, cabendo tanto à iniciativa privada quanto ao poder público as ações de planejamento e execução de obras para escoamento da produção, por exemplo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q29 Item 4 (TPS 2015): O Brasil, terceira maior potência mundial agropecuária, enfrenta desafios logísticos, de infraestrutura e legais para continuar a crescer nesse setor, competindo internacionalmente. No que se refere a esse assunto e aos múltiplos aspectos a ele relacionados, julgue (C ou E) os itens a seguir. | Denominam-se demandas corporativas os investimentos públicos que, na visão política nacional, são destinados a superar as deficiências em transporte, conferir competitividade e promover o crescimento sustentável do país, a partir do investimento estatal no setor de logística, considerado área estratégica de segurança nacional. ||154IRBRDIPLOMATA2015_001_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q30 Item 1 (TPS 2015): O século XX terminou, sobretudo, sob o signo da mundialização do capital e sob o fim do socialismo nos países do Leste Europeu. Os países do terceiro mundo com dívidas externas elevadas submeteram-se de forma pacífica às políticas impostas pelo FMI. O Brasil assistiu, no início da década de 90, dois planos de controle financeiro e inflacionário, primeiro o Plano Collor e o confisco temporário do dinheiro depositado nos bancos. Em 1992, o país assistiu a Eco-92 e a pressão política sobre seu gove | Foram criados, nas últimas décadas, mecanismos de transferência de recursos do fundo público para o agronegócio brasileiro, de modo a viabilizar a cultura da soja para o mercado mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q30 Item 2 (TPS 2015): O século XX terminou, sobretudo, sob o signo da mundialização do capital e sob o fim do socialismo nos países do Leste Europeu. Os países do terceiro mundo com dívidas externas elevadas submeteram-se de forma pacífica às políticas impostas pelo FMI. O Brasil assistiu, no início da década de 90, dois planos de controle financeiro e inflacionário, primeiro o Plano Collor e o confisco temporário do dinheiro depositado nos bancos. Em 1992, o país assistiu a Eco-92 e a pressão política sobre seu gove | Entre o ideário econômico do moderno agronegócio e os movimentos sociais pela reforma agrária, o primeiro destacou-se em meados da década de 90 do século XX, com o apoio da mídia e do governo brasileiros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q30 Item 3 (TPS 2015): O século XX terminou, sobretudo, sob o signo da mundialização do capital e sob o fim do socialismo nos países do Leste Europeu. Os países do terceiro mundo com dívidas externas elevadas submeteram-se de forma pacífica às políticas impostas pelo FMI. O Brasil assistiu, no início da década de 90, dois planos de controle financeiro e inflacionário, primeiro o Plano Collor e o confisco temporário do dinheiro depositado nos bancos. Em 1992, o país assistiu a Eco-92 e a pressão política sobre seu gove | Grande parte do desmatamento na Amazônia é consequência direta de atividades predatórias desenvolvidas por grileiros de terras pública e(ou) devolutas, madeireiros e pecuaristas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Economia', NULL, 'Q30 Item 4 (TPS 2015): O século XX terminou, sobretudo, sob o signo da mundialização do capital e sob o fim do socialismo nos países do Leste Europeu. Os países do terceiro mundo com dívidas externas elevadas submeteram-se de forma pacífica às políticas impostas pelo FMI. O Brasil assistiu, no início da década de 90, dois planos de controle financeiro e inflacionário, primeiro o Plano Collor e o confisco temporário do dinheiro depositado nos bancos. Em 1992, o país assistiu a Eco-92 e a pressão política sobre seu gove | O aumento mundial da produção de soja, na última década, decorre das possibilidades reais de expansão de sua área cultivada em nível global, frente à diminuição dessas áreas em países da América do Sul, como Brasil, Argentina e Paraguai.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q31 Item 1 (TPS 2015): A segregação residencial é um dos mais expressivos processos espaciais que geram a fragmentação do espaço urbano. As áreas sociais são a sua manifestação espacial, a forma resultante do processo. Forma e processo levam a ver a cidade como um “mosaico social”. A partir da segregação das áreas sociais, originam-se inúmeras atividades econômicas espacialmente diferenciadas, como centros comerciais e áreas industriais. O inverso também é verdadeiro: a partir da concentração de indústrias na cidade,  | Most of the recent scholarly works on the evolution of diplomacy highlight the added complexity in which “states and other international actors communicate, negotiate and', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2015, 'Geografia', NULL, 'Q31 Item 2 (TPS 2015): A segregação residencial é um dos mais expressivos processos espaciais que geram a fragmentação do espaço urbano. As áreas sociais são a sua manifestação espacial, a forma resultante do processo. Forma e processo levam a ver a cidade como um “mosaico social”. A partir da segregação das áreas sociais, originam-se inúmeras atividades econômicas espacialmente diferenciadas, como centros comerciais e áreas industriais. O inverso também é verdadeiro: a partir da concentração de indústrias na cidade,  | otherwise interact” in the 21st century. Diplomacy has to take into account “the crazy-quilt nature of modern interdependence”. Decision-making on the international stage 7 involves what has been depicted as “two level games” or “double-edged diplomacy”. With accentuated forms of globalization the scope of diplomacy as the “engine room” of 10 International Relations has moved beyond the traditional core concerns to encompass a myriad set of issue areas. And the boundari', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
